def f(g):
    sep={i for i,r in enumerate(g) if all(c==4 for c in r)}
    top=min(sep); P=g[:top]; out=[r[:] for r in g]; last=top
    for i in range(top+1,len(g)):
        if i in sep: last=i
        else: out[i]=P[(i-last-1)%len(P)][:]
    return out
