def f(g):
    bg=g[0][0]
    sep=sorted(i for i,r in enumerate(g) if len(set(r))==1 and r[0]!=bg)
    top=sep[0]; h=top
    best={}
    for j0 in range(h):
        cands=[g[j0]]
        for s in sep:
            k=s+1+j0
            if k<len(g) and k not in sep: cands.append(g[k])
        best[j0]=max(cands,key=lambda r: sum(1 for c in r if c!=bg))[:]
    out=[]
    for j in range(len(g)):
        out.append(g[j][:] if j in sep else best[(j-top-1)%h if j>top else j])
    return out
