from collections import Counter
def f(g):
    bg=Counter(c for r in g for c in r).most_common(1)[0][0]
    hsep=sorted(i for i,r in enumerate(g) if len(set(r))==1 and r[0]!=bg)
    top=hsep[0]; h=top; W=len(g[0])
    vsep=sorted(j for j in range(W) if len(set(g[i][j] for i in range(len(g))))==1 and g[0][j]!=bg)
    # segments between vsep cols
    bounds=[-1]+vsep+[W]
    segs=[(bounds[k]+1,bounds[k+1]) for k in range(len(bounds)-1) if bounds[k]+1<bounds[k+1]]
    dec={}
    for j0 in range(h):
        d={}
        rows=[g[j0]]+[g[s+1+j0] for s in hsep if s+1+j0<len(g) and s+1+j0 not in hsep]
        for r in rows:
            for c,v in enumerate(r):
                if v!=bg and c not in vsep and not any(a<=c<b for a,b in []):
                    d[c]=v
        dec[j0]=d
    out=[]; last=top
    for i in range(len(g)):
        if i in hsep: out.append(g[i][:]); last=i; continue
        j0=i if i<top else (i-last-1)%h
        row=[bg]*W
        for c in vsep: row[c]=g[i][c]
        for c,v in dec[j0].items():
            row[c]=v
            for a,b in segs:
                if a<=c<b:
                    for a2,b2 in segs:
                        r=c-a
                        if r<b2-a2: row[a2+r]=v
        out.append(row)
    return out
